public void arrival(Map  _journalTransMap)
{
    InventDim                   tmpInventDim;
    InventDim                   inventDimReceipt;
    WMSJournalTrans             wMSJournalTrans;
    LineNum                     lineNum;
    #tfm

    lineNum  = str2num(strReplace(this.InventTransId, ',', '.'));

    //wMSJournalTrans = WMSJournalTrans::find(this.InventRefId, lineNum, true);
    select firstonly forupdate wMSJournalTrans where wMSJournalTrans.journalId == this.InventRefId && wMSJournalTrans.inventTransId == this.InventTransId;
    if (wMSJournalTrans)
    {
        if (wMSJournalTrans.qty > this.InventQty)
        {
            wMSJournalTrans = MobRegistrations::WmsJournalTransSplit(wMSJournalTrans, this.inventQty);
        }
        if (!_journalTransMap.exists(wMSJournalTrans.RecId))
        {
            wMSJournalTrans.qty     = this.InventQty;
            _journalTransMap.insert(wMSJournalTrans.RecId, wMSJournalTrans);

            inventDimReceipt = InventDim::find(this.ToInventDimId());
            tmpInventDim     = InventDim::find(wMSJournalTrans.inventDimId);

            tmpInventDim.wMSLocationId  = inventDimReceipt.WMSLocationId;
            tmpInventDim.LicensePlateId = inventDimReceipt.LicensePlateId;
            #if.isAX6
            tmpInventDim.wMSPalletId     = inventDimReceipt.wMSPalletId;
            #endif

            if (inventDimReceipt.InventBatchId)
            {
                this.findOrCreateBatchSetExpDate(InventTrans::findTransId(wMSJournalTrans.inventTransId), inventDimReceipt.inventBatchId);
            }

            tmpInventDim.inventBatchId      = inventDimReceipt.InventBatchId;
            tmpInventDim.inventSerialId     = inventDimReceipt.InventSerialId;

            wMSJournalTrans.InventDimId   = InventDim::findOrCreate(tmpInventDim).InventDimId;

            if (this.ReturnDispositionCodeId == TFMConstants::RMA_QA())
            {
                wMSJournalTrans.createQuarantineOrder = NoYes::Yes;
            }
            else
            {
                wMSJournalTrans.createQuarantineOrder = NoYes::No;
                wMSJournalTrans.ReturnDispositionCodeId = this.ReturnDispositionCodeId;
            }

            // Only check the picking and buffer locations for pallet transfers

            // Items registered on the mobile device will specify the final location where the item is placed
            // There is no need to get AX to check anything
            wMSJournalTrans.checkPickingLocation = false;

            wMSJournalTrans.update();
        }
    }
}

public void counting()
{
    InventJournalTrans  inventJournalTrans  = InventJournalTrans::findInventTransId(this.InventTransId, true);
    InventDim           inventDim;
    InventJournalId     JournalId = inventJournalTrans.JournalId;
    WHSLicensePlateId   licensePlate = inventJournalTrans.inventDim().LicensePlateId;
    this.countLine(inventJournalTrans);

    if (!inventJournalTrans.inventJournalTable().MobCountByLP || !licensePlate)
    {
        return;
    }

    while select inventJournalTrans where inventJournalTrans.JournalId == JournalId && inventJournalTrans.InventTransId != this.inventtransid
        join LicensePlateId from inventDim where inventDim.inventDimId == inventJournalTrans.inventDimId && inventDim.LicensePlateId == licensePlate
    {
        this.countLine(inventJournalTrans);
    }

    /*InventDimParm       InventDimParm;
    inventDimParm.initFromInventDim(inventJournalTrans.inventDim());
    InventQty           inventQty = InventSumDatePhysicalDim::onHandQty(TFMHelper::today(),inventJournalTrans.ItemId,inventJournalTrans.inventDim(),inventDimParm);

    inventJournalTrans.Counted                  = inventJournalTrans.inventJournalTable().TFMCountByLP && inventJournalTrans.inventDim().LicensePlateId ? inventQty : this.InventQty;
    inventJournalTrans.Worker                   = HcmWorker::userId2Worker(curuserId());
    inventJournalTrans.inventMovement().journalSetCounted();
    inventJournalTrans.TFMRegisteredOnMobileWMS   = NoYes::Yes;
    inventJournalTrans.update();*/
}

public void countLine(InventJournalTrans  _inventJournalTrans)
{
    InventDimParm       InventDimParm;
    inventDimParm.initFromInventDim(_inventJournalTrans.inventDim());
    InventQty           inventQty = InventSumDatePhysicalDim::onHandQty(TFMHelper::today(),_inventJournalTrans.ItemId,_inventJournalTrans.inventDim(),inventDimParm);

    _inventJournalTrans.Counted                  = _inventJournalTrans.inventJournalTable().MobCountByLP && _inventJournalTrans.inventDim().LicensePlateId ? inventQty : this.InventQty;
    _inventJournalTrans.Worker                   = HcmWorker::userId2Worker(curuserId());
    _inventJournalTrans.inventMovement().journalSetCounted();
    _inventJournalTrans.MobRegisteredOnMobile   = NoYes::Yes;
    _inventJournalTrans.update();
}

public void countingTag()
{
    InventJournalTrans_Tag  inventJournalTrans_Tag;

    select firstonly forupdate inventJournalTrans_Tag
        where inventJournalTrans_Tag.RecId == str2int64(this.InventTransId);

    inventJournalTrans_Tag.qty                      = this.InventQty;
    inventJournalTrans_Tag.Worker                   = HcmWorker::userId2Worker(curuserId());
    inventJournalTrans_Tag.MobRegisteredOnMobile   = NoYes::Yes;
    inventJournalTrans_Tag.update();
}

/// <summary>
/// If the location, batch or serialno received from the mobile device is different from the one specified on the git order
/// then we move the item using the unplanned move functionality
///
/// </summary>
/// <param name = "_gitOrder">The ITMGoodsInTransitOrder where the batch and locations could be changed.</param>
public void moveDimensionForGitOrder(ITMGoodsInTransitOrder _gitOrder)
{
    WMSLocationId                   fromWmsLocationId;
    WMSLocationId                   toWmsLocationId;
    InventLocationId                toInventLocationId;
    InventTrans                     gitInventTrans;
    InventBatchId                   toInventBatchId;
    InventSerialId                  toSerialId;
    InventDim                       inventDimIssue;
    InventDim                       inventDimReceipt;
    TFMInventDimSetup               mobInventDimSetup;
    Map							    qtys = new Map(Types::String,Types::Real);
    Map							    itemIds = new Map(Types::String,Types::String);
    Map							    inventDimIssues = new Map(Types::String,Types::Record);
    Map							    inventDimReceipts = new Map(Types::String,Types::Record);

    inventDimIssue = _gitOrder.inventDim();
    fromWmsLocationId = inventDimIssue.wMSLocationId;
    inventDimReceipt = InventDim::find(this.ToInventDimId(), false);
    toInventLocationId = inventDimReceipt.InventLocationId;

    toWmsLocationId = WMSLocation::find( inventDimReceipt.wMSLocationId,  inventDimIssue.inventLocationId ).wMSLocationId;
    toWmsLocationId = toWmsLocationId ? toWmsLocationId : fromWmsLocationId;

    gitInventTrans = InventTrans::findTransId(_gitOrder.InventTransId);

    if(inventDimReceipt.inventBatchId && inventDimReceipt.inventBatchId != inventDimIssue.inventBatchId)
    {
        toInventBatchId = inventDimReceipt.inventBatchId;
        this.findOrCreateBatchSetExpDate(gitInventTrans, inventDimReceipt.inventBatchId);
    }

    if (inventDimReceipt.inventSerialId && inventDimReceipt.inventSerialId != inventDimIssue.inventSerialId)
    {
        toSerialId = inventDimReceipt.inventSerialId;
        this.findOrCreateSerialId(gitInventTrans, inventDimReceipt.inventSerialId);
    }

    // If the batch, serial or location received from the mobile device is different from the one specified on the git order then change the Dim.
    if (toInventBatchId || toSerialId || (toWmsLocationId && fromWmsLocationId != toWmsLocationId))
    {
        // Get the dimension setup for the item
        mobInventDimSetup = TFMInventDimSetup::Construct(inventTable::find(_gitOrder.ItemId));

        inventDimReceipt.data(inventDimIssue);
        inventDimReceipt.wmsLocationId = toWmsLocationId;
        if(toInventLocationId)
        {
            inventDimReceipt.inventLocationid = toInventLocationId;
        }

        if(toInventBatchId)
        {
            inventDimReceipt.inventBatchId = toInventBatchId;
        }


        if(toSerialId)
        {
            inventDimReceipt.inventSerialId = toSerialId;
        }

        inventDimReceipt = InventDim::findOrCreate(inventDimReceipt);

        // If the item is using pallet id the pallet must be moved with the MovePallet function
        // Otherwise we move the item using the unplanned move
        // Determine if a pallet id or location should be used
        if (mobInventDimSetup.registerLicensePlate())
        {
            qtys.insert('1', this.Qty);
            itemIds.insert('1',_gitOrder.ItemId);
            inventDimIssues.insert('1',inventDimIssue);
            inventDimReceipts.insert('1',inventDimReceipt);
            MobPostHelper::inventJournalTransferMulti(qtys,itemIds,inventDimIssues, inventDimReceipts);
        }
        else
        {
            MobPostHelper::inventJournalTransfer(this.Qty,_gitOrder.ItemId,inventDimIssue, inventDimReceipt, !(!toSerialId));
        }
    }
}

private void findOrCreateBatchSetExpDate(InventTrans _inventTrans, InventBatchId _inventBatchId)
{
    InventBatch         inventBatch = InventBatch::find(_inventBatchId, _inventTrans.ItemId, true);
    str                 pdsVendBatchDateStr = this.getExtraInfoValue(MobConstants::pdsvendbatchdate());
    PdsVendBatchDate    pdsVendBatchDate = pdsVendBatchDateStr ? str2Date(pdsVendBatchDateStr, 123) : dateNull();
    str                 pdsVendExpiryDateStr = this.getExtraInfoValue(MobConstants::pdsvendexpirydate());
    PdsVendExpiryDate   pdsVendExpiryDate = pdsVendExpiryDateStr ? str2Date(pdsVendExpiryDateStr, 123) : dateNull();

    if (!inventBatch)
    {
        inventBatch.initFromInventTrans(_inventTrans);
        inventBatch.itemId          = _inventTrans.ItemId;
        inventBatch.inventBatchId   = _inventBatchId;
    }

    if (this.expDate)
    {
        inventBatch.expDate = this.expDate;
    }
    if (pdsVendBatchDate != dateNull() && !inventBatch.PdsVendBatchDate)
    {
        inventBatch.PdsVendBatchDate    = pdsVendBatchDate;
    }
    if (pdsVendExpiryDate != dateNull() && !inventBatch.PdsVendExpiryDate)
    {
        inventBatch.PdsVendExpiryDate   = pdsVendExpiryDate;
    }
    inventBatch.write();

    if (this.expDate && this.expDate != inventBatch.expDate)
    {
        inventBatch.expDate = this.expDate;
        inventBatch.write();
    }
}

private void updateBatchExpDate(RefRecId _InventTransRecId)
{
    InventTrans     inventTrans = InventTrans::findRecId(_InventTransRecId);
    InventBatch     inventBatch = InventBatch::find(inventTrans.inventBatchId(), inventTrans.ItemId, true);

    if(inventBatch && !inventBatch.expDate)
    {
        inventBatch.expDate = this.expDate;
        inventBatch.update();
    }
}

