private void findOrCreateSerialId(InventTrans _inventTrans, InventSerialId _inventSerialId)
{
    InventSerial inventSerial = InventSerial::find(_inventSerialId, _inventTrans.ItemId, true);

    if (!inventSerial)
    {
        inventSerial.itemId         = _inventTrans.ItemId;
        inventSerial.inventSerialId = _inventSerialId;
    }

    inventSerial.write();
}

/// <summary>
/// Finds the itemnumber, from the origin.
/// Uses InventRefType, InventTransId, InventRefId, RefRecId
/// </summary>
/// <returns>
/// ItemId if found
/// </returns>
/// <remarks>
///
/// </remarks>

public display ItemId ItemNumber()
{
    ItemId          itemId;
    LineNum         lineNum;
    //WMSJournalTrans wmsTrans;


    switch (this.InventRefType)
    {
        case MobInventRefType::InventArrival:
            lineNum  = str2num(strReplace(this.InventTransId, ',', '.'));
            itemId = WMSJournalTrans::find(this.InventRefId, lineNum).itemId;
            break;

        case MobInventRefType::Purch:
            itemId = PurchLine::findInventTransId(this.InventTransId).ItemId;
            break;

        case MobInventRefType::InventTransfer:
            itemId = InventTransferLine::findTransIdShip(this.InventTransId).ItemId;
            if (!itemId)
            {
                itemId = InventTransferLine::findTransIdReceive(this.InventTransId).ItemId;
            }
            break;

        case MobInventRefType::Sales:
            itemId = SalesLine::findInventTransId(this.InventTransId).ItemId;
            break;

        case MobInventRefType::None:
            itemId = (select firstonly WMSOrderTrans where WMSOrderTrans.RecId == this.RefRecId).ItemId;
            break;

        case MobInventRefType::ProdLine:
            itemId = (select firstonly prodJournalBom where prodJournalBom.InventTransId == this.InventTransId).ItemId;
            break;

        case MobInventRefType::InventJournal:
            itemId = (select firstOnly InventJournalTrans where InventJournalTrans.RecId == this.RefRecId).ItemId;
            break;
    }
    if (!itemId && this.InventTransId)
    {
        itemId = InventTransOrigin::findByInventTransId(this.InventTransId).ItemId;
    }

    return itemId;
}

// pick as much as possible instead of full quantity
public void pick()
{
    InventMovement              movement;
    InventTrans                 inventTrans;
    TmpInventTransWMS           tmpInventTransWMS;
    InventDim                   tmpInventDim;
    InventTransSplit            inventTransSplit;
    RefRecId                    refRecId;
    ProdJournalBOM              prodJournalBOM;
    InventQty                   totalQtyToPick;
    InventQty                   remainingQtyToPick;
    InventTransType             inventTransType;
    InventTransRefId            inventTransRefId;
    InventDim                   inventDimIssue;
    inventTransOrigin           inventTransOrigin;
    Map                         mapQtyByTmpInventTransWMS;          //tmpInventTransWMS recId -> map InventTrans recId -> qty
    Map                         mapInventTransInventTransOrigin;    //inventTrans recId       -> InventTransOrigin recId
    Map                         mapQtyByInventTrans;                //inventTrans recId       -> selectedQty
    InventTransferLine          inventTransferLine;
    InventTransChildRefId		childRefID;
    #tfm
    totalQtyToPick = this.InventQty;
    remainingQtyToPick = totalQtyToPick;

    // If quantity is zero, skip and return
    if(this.InventQty == 0)
    {
        return;
    }

    if (this.InventRefType == MobInventRefType::Sales)
    {
        movement            = InventMovement::construct(SalesLine::findInventTransId(this.inventTransId));
        inventTransType     = InventTransType::Sales;
        inventTransRefId    = this.InventRefId;
    }

    if (this.InventRefType == MobInventRefType::InventTransfer)
    {
        inventTransferLine = InventTransferLine::findTransIdShip(this.InventTransId);
        movement = InventMovement::construct( inventTransferLine );
        inventTransType = InventTransType::TransferOrderShip;
        inventTransRefId = inventTransferLine.TransferId;
    }

    if (this.InventRefType == MobInventRefType::Purch)
    {

        movement            = InventMovement::construct(PurchLine::findInventTransId(this.inventTransId));
        inventTransType = InventTransType::Purch;
        inventTransRefId = this.InventRefId;
    }

    if (this.InventRefType == MobInventRefType::ProdLine)
    {
        select firstonly forupdate prodJournalBOM
            index hint TransIdIdx
            where prodJournalBOM.RecId			== this.RefRecId
                && prodJournalBOM.JournalId     == this.InventRefId;

        if (prodJournalBOM)
        {
            movement            = InventMovement::construct(prodJournalBOM);
            inventTransType     = InventTransType::ProdLine;
            inventTransRefId    = prodJournalBOM.ProdId;
            this.inventTransId	= prodJournalBOM.InventTransId;
            childRefID			= prodJournalBOM.InventTransChildRefId;
        }
    }

    //prepare pick

    //select open trans
    while select RecId from inventTransOrigin
        where inventTransOrigin.InventTransId  == this.InventTransId
        && inventTransOrigin.ReferenceCategory == inventTransType
    join inventTrans
        where (inventTrans.StatusIssue  == StatusIssue::ReservPhysical ||
                inventTrans.StatusIssue  == StatusIssue::OnOrder) &&
                inventTransOrigin.RecId == inventTrans.InventTransOrigin &&
                (inventTrans.TransChildRefId == childRefID || !childRefID)

    {
        mapQtyByTmpInventTransWMS       = new Map(Types::Int64,Types::Class);
        mapInventTransInventTransOrigin = new Map(Types::Int64,Types::Int64);
        mapQtyByInventTrans             = new Map(Types::Int64,Types::Container);


        //less quantity (split needed)
        if (abs(remainingQtyToPick) < -inventTrans.Qty && !InventTable::find(inventTrans.ItemId).modelGroup().NegativePhysical)   //inventTrans.Qty neg. on issue
        {
            //split
            inventTransSplit   = InventTransSplit::construct();
            inventTransSplit.parmInventTrans(inventTrans);
            inventTransSplit.parmSplitQty(-abs(remainingQtyToPick));
            #ifnot.isAx6
            inventTransSplit.runOperation();
            #endif
            #if.isAX6
            inventTransSplit.run();
            #endif
            refRecId = inventTransSplit.updRecId();    //returns the new recid

            inventTrans = InventTrans::findRecId(refRecId);
        }

        //save registrations
        tmpInventTransWMS.initFromInventTrans(inventTrans);
        tmpInventTransWMS.InventQty = -inventTrans.Qty;
        tmpInventTransWMS.ReferenceId = this.InventRefId;
        tmpInventTransWMS.ReferenceCategory = inventTransType;
        tmpInventTransWMS.ItemId = inventTrans.ItemId;
        inventDimIssue = InventDim::find(this.InventDimId());

        //set invent dimensions
        tmpInventDim = InventDim::find(inventTrans.inventDimId);
        tmpInventDim.wMSLocationId      = inventDimIssue.WMSLocationId;
        tmpInventDim.inventBatchId      = inventDimIssue.InventBatchId;
        tmpInventDim.inventSerialId     = inventDimIssue.InventSerialId;
        tmpInventDim.LicensePlateId     = inventDimIssue.LicensePlateId;
        #if.isAX6
        tmpInventDim.wMSPalletId     = inventDimIssue.wMSPalletId;
        #endif
        TFMHelper::EnsureInventDim(tmpInventDim);
        tmpInventTransWMS.InventDimId   = InventDim::findOrCreate(tmpInventDim).InventDimId;
        tmpInventTransWMS.insert();

        mapInventTransInventTransOrigin.insert(inventTrans.RecId,inventTransOrigin.RecId);

        mapQtyByInventTrans.insert(inventTrans.RecId,[-inventTrans.Qty]);

        mapQtyByTmpInventTransWMS.insert(tmpInventTransWMS.RecId,mapQtyByInventTrans);
        InventTransWMS_Pick_Mob::MobUpdateInventServer(tmpInventTransWMS,mapQtyByTmpInventTransWMS.pack(),mapInventTransInventTransOrigin.pack());

        remainingQtyToPick -= tmpInventTransWMS.InventQty;

        if (remainingQtyToPick <= 0)
        {
            break;
        }
    }

    if (remainingQtyToPick > 0)
    {
        throw error(TFMHelper::strfmt("@TFM:MEL8", [totalQtyToPick]));
    }
}

public void insert()
{
    super();
    if (this.ToteID)
    {
        MobToteTable::FindOrCreate(this.ToteID,InventDim::find(this.InventDimId ? this.InventDimId : this.ToInventDimId));
        MobToteContent::addContent(this.ToteID,this.Qty, this.RefRecId, this.InventDimId);
    }
}

// pick as much as possible instead of full quantity
public Map pickWMS(Map _selectedLines)
{
    InventDim                   tmpInventDim;
    InventQty                   totalQtyToPick;
    InventQty                   remainingQtyToPick;
    WMSOrderTrans               localSplittedOrderTrans;
    WMSPickingRoute             pickingRoute;
    WMSOrderTrans               wmsOrderTrans;
    WmsOrderTransType_Output_OrderPick           wmsOrderTransType;
    InventDim                   inventDimIssue;
    Map                         localSelectedLines;
    boolean                     negativePhysical;
    InventOnhandQty             inventOnHandQty;
    InventQty                   iqty;
    InventDimParm               inventDimParmFrom;
    boolean                     overpicking;
    #tfm

    // If quantity is zero, skip and return
    if(this.InventQty == 0)
    {
        return _selectedLines;
    }

    if (this.InventRefType != MobInventRefType::None)
    {
        throw error(strfmt("@SYS118114",funcname()));
    }
    pickingRoute = WMSPickingRoute::find(this.InventRefId);

    if (!this.InventRefId || !pickingRoute)
    {
        throw error(strfmt("@SYS15067",this.InventRefId ? this.InventRefId : this.InventTransId)); //using the InventTransID to provide info even though it is not an order.
    }
    totalQtyToPick = this.InventQty;
    remainingQtyToPick = totalQtyToPick;

    //select open trans
    ttsbegin;
    while select firstonly forupdate wmsOrderTrans
        where wmsOrderTrans.RecId == this.RefRecId &&
              wmsOrderTrans.expeditionStatus != WMSExpeditionStatus::Complete
    {
        if (!_selectedLines.exists(wmsOrderTrans.RecId))
        {
            // set invent dimensions
            // The registrations from the mobile device can either be of type TAKE or PLACE
            // TAKE registrations relate to where items are taken from
            // PLACE registration relate to where items are placed

            inventDimIssue = InventDim::find(this.InventDimId());
            tmpInventDim = InventDim::find(wmsOrderTrans.inventDimId);
            tmpInventDim.wMSLocationId      = inventDimIssue.WMSLocationId;
            tmpInventDim.inventBatchId      = inventDimIssue.InventBatchId;
            tmpInventDim.inventSerialId     = inventDimIssue.InventSerialId;
            tmpInventDim.LicensePlateId     = inventDimIssue.LicensePlateId;
            #if.isAX6
            tmpInventDim.wMSPalletId     = inventDimIssue.wMSPalletId;
            #endif

            // If serial number is active but only for sales we need to handle serial number dimension
            if(TFMInventDimHelper::SerialNumberIsactiveInSalesOnly(wmsOrderTrans.itemId))
            {
                InventTrackingRegisterTrans::createFromSerial(inventDimIssue.inventSerialId, wmsOrderTrans.inventTransId, false);
                tmpInventDim.inventSerialId = '';
            }

            TFMHelper::EnsureInventDim(tmpInventDim);
            wmsOrderTransType = WMSOrderTransType_Output_OrderPick::newWMSOrderTrans(wmsOrderTrans) as WmsOrderTransType_Output_OrderPick;

            // Make sure that the new invent dim exists before the CheckFinishPickingLine function is called
            tmpInventDim.inventDimId = '';
            tmpInventDim = InventDim::findOrCreate(tmpInventDim);
            inventDimParmFrom.initFromInventDim(tmpInventDim);
            inventOnHandQty = InventOnHandQty::newPArameters(wmsOrderTrans.ItemId, tmpInventDim, inventDimParmFrom);
            iqty = inventOnHandQty.physicalInvent();
            overpicking = remainingQtyToPick > wmsOrderTrans.qty;
            wmsOrderTrans = wmsOrderTransType.MobCheckFinishPickingLine(tmpInventDim, remainingQtyToPick, iqty);

            negativePhysical = InventTable::find(wmsOrderTrans.ItemId).modelGroup().NegativePhysical;

            if (wmsOrderTrans.RecId != this.RefRecId && this.ToteID)
            {
                //Split was made. Update Tote

                //TODO: Add the updateContent in Mob
                //TFMToteContent::updateContent(this.ToteID,wmsOrderTrans.qty, this.RefRecId, wmsOrderTrans.RecId);
            }

            // Set the new InventDim on the pick line
            wmsOrderTrans.InventDimId = tmpInventDim.inventDimId;

            _selectedLines.insert(wmsOrderTrans.RecId,[wmsOrderTrans.OrderId,wmsOrderTrans.RecVersion]);

            localSelectedLines = new Map(Types::Int64,Types::Container);


            if (negativePhysical && iqty-remainingQtyToPick < 0 && wmsOrderTrans.RecId != this.RefRecId)
            {
                if (wmsOrderTransType.getExtraSplittedLine().recid)
                {
                    localSplittedOrderTrans = wmsOrderTransType.getExtraSplittedLine();
                }
                else
                {
                    select firstonly forupdate RecVersion, recid from localSplittedOrderTrans where localSplittedOrderTrans.RecId == this.RefRecId;
                }
                if (localSplittedOrderTrans)
                {
                    if (overpicking)
                    {
                        localSplittedOrderTrans.qty = remainingQtyToPick- wmsOrderTrans.qty;
                        localSplittedOrderTrans.wmsOrderTransType().updateQty();
                        localSplittedOrderTrans.update();
                    }
                    localSelectedLines.insert(localSplittedOrderTrans.RecId,[wmsOrderTrans.OrderId,localSplittedOrderTrans.RecVersion]);
                }

            }
            else
            {
                wmsOrderTrans.qty = totalQtyToPick;
                wmsOrderTrans.wmsOrderTransType().updateQty();
                wmsOrderTrans.update();
            }
            localSelectedLines.insert(wmsOrderTrans.RecId,[wmsOrderTrans.OrderId,wmsOrderTrans.RecVersion]);

            WMSOrderTransType::finishPickingLinesMulti(localSelectedLines.pack(),'',pickingRoute.operatorWorker);

            remainingQtyToPick -= (wmsOrderTrans.Qty + localSplittedOrderTrans.qty);
        }
    }
    ttscommit;

    if (remainingQtyToPick > 0 && !negativePhysical)
    {
        throw error(TFMHelper::strfmt("@TFM:MEL8", [totalQtyToPick]));
    }
    return _selectedLines;
}

// register as much as possible instead of full quantity
public server void register()
{
    InventMovement              movement;
    InventTrans                 inventTrans;
    TmpInventTransWMS           tmpInventTransWMS;
    InventDim                   tmpInventDim;
    InventTransSplit            inventTransSplit;
    RefRecId                    refRecId;
    InventQty                   totalQtyToReg;
    InventQty                   remainingQtyToReg;
    InventTransType             inventTransType;
    InventTransRefId            inventTransRefId;
    InventDim                   inventDimReceipt;
    inventTransOrigin           inventTransOrigin;
    Map                         mapQtyByTmpInventTransWMS;          //tmpInventTransWMS recId -> map InventTrans recId -> qty
    Map                         mapInventTransInventTransOrigin;    //inventTrans recId       -> InventTransOrigin recId
    Map                         mapQtyByInventTrans;                //inventTrans recId       -> selectedQty

    #tfm
    totalQtyToReg = this.InventQty;
    remainingQtyToReg = totalQtyToReg;

    switch (this.InventRefType)
    {
        case MobInventRefType::Purch :
            movement            = InventTransWMS_Register::inventMovement(PurchLine::findInventTransId(this.inventTransId));
            inventTransRefId    = this.InventRefId;
            inventTransType     = InventTransType::Purch;

            break;

        case MobInventRefType::InventTransfer :

            movement            = InventTransWMS_Register::inventMovement(InventTrans::findTransId(InventTransferLine::findTransIdReceive(this.inventTransId).InventTransId));
            inventTransType     = InventTransType::TransferOrderReceive;
            inventTransRefId    = this.InventRefId;

            if  (movement.newMovement_TransferReceipt())
            {
                movement =  movement.newMovement_TransferReceipt();
                movement =  movement.newMovement_TransferIssueReceive() ?  movement.newMovement_TransferIssueReceive() : movement;
                movement =  movement.newMovement_TransferReceipt() ? movement.newMovement_TransferReceipt()  : movement;
            }
            break;

        case MobInventRefType::InventArrival :

            movement            = InventMovement::construct(PurchLine::findInventTransId(this.inventTransId));
            inventTransType     = InventTransType::Purch;
            inventTransRefId    = this.InventRefId;
            break;
    }

    //select open trans
    while select inventTrans
        where inventTrans.StatusReceipt == StatusReceipt::Ordered
    join inventTransOrigin
        where inventTransOrigin.InventTransId == this.InventTransId &&
              inventTransOrigin.ReferenceCategory == inventTransType &&
              inventTransOrigin.ReferenceId == inventTransRefId &&
              inventTransOrigin.RecId == inventTrans.InventTransOrigin
    {

        mapQtyByTmpInventTransWMS       = new Map(Types::Int64,Types::Class);
        mapInventTransInventTransOrigin = new Map(Types::Int64,Types::Int64);
        mapQtyByInventTrans             = new Map(Types::Int64,Types::Real);

        //less quantity (split needed)
        if (remainingQtyToReg < inventTrans.Qty)
        {
            //split
            inventTransSplit   = InventTransSplit::construct();
            inventTransSplit.parmInventTrans(inventTrans);
            inventTransSplit.parmSplitQty(remainingQtyToReg);

            #ifnot.isAx6
            inventTransSplit.runOperation();
            #endif
            #if.isAX6
            inventTransSplit.run();
            #endif
            refRecId = inventTransSplit.updRecId();    //returns the new recid

            inventTrans = InventTrans::findRecId(refRecId);
        }

        //save registrations
        tmpInventTransWMS.initFromInventTrans(inventTrans);
        tmpInventTransWMS.initFromInventTransOrigin(inventTransOrigin);
        tmpInventTransWMS.InventQty =  remainingQtyToReg;

        inventDimReceipt = InventDim::find(this.ToInventDimId());

        if (inventDimReceipt.InventBatchId)
        {
            this.findOrCreateBatchSetExpDate(inventTrans, inventDimReceipt.inventBatchId);
        }

        if (inventDimReceipt.inventSerialId)
        {
            this.findOrCreateSerialId(inventTrans, inventDimReceipt.inventSerialId);
        }

        //set invent dimensions
        tmpInventDim                    = InventDim::find(inventTrans.inventDimId);

        tmpInventDim.wMSLocationId      = inventDimReceipt.WMSLocationId;

        tmpInventDim.inventBatchId      = inventDimReceipt.InventBatchId;
        tmpInventDim.inventSerialId     = inventDimReceipt.InventSerialId;
        tmpInventDim.LicensePlateId     = inventDimReceipt.LicensePlateId;
        #if.isAX6
        tmpInventDim.wMSPalletId     = inventDimReceipt.wMSPalletId;
        #endif
        TFMHelper::EnsureInventDim(tmpInventDim);
        tmpInventTransWMS.InventDimId   = InventDim::findOrCreate(tmpInventDim).InventDimId;
        tmpInventTransWMS.insert();

        mapInventTransInventTransOrigin.insert(inventTrans.RecId,inventTransOrigin.RecId);

        mapQtyByInventTrans.insert(inventTrans.RecId,inventTrans.Qty);

        mapQtyByTmpInventTransWMS.insert(tmpInventTransWMS.RecId,mapQtyByInventTrans);

        remainingQtyToReg -= tmpInventTransWMS.InventQty;

        if (false == InventTransWMS_Register_Mob::MobUpdateInventOnServer(inventTrans,
                                                            tmpInventTransWMS,
                                                            mapQtyByTmpInventTransWMS.pack(),
                                                            mapInventTransInventTransOrigin.pack()))
        {
            throw error("@SYS40031");
        }

        // Check if expiration date is set on autocreated batch ID
        if(this.expDate && !inventDimReceipt.inventBatchId)
        {
            this.updateBatchExpDate(refRecId);  
        }
        break;
    }

    if (remainingQtyToReg > 0.0)
    {
        throw error(TFMHelper::strfmt("@TFM:MEL8", [totalQtyToReg]));
    }
}

protected InventDimId ToInventDimID()
{
    return this.ToInventDimId ? this.ToInventDimId : this.InventDimId;
}

protected InventDimId InventDimID()
{
    return !this.InventDimId ? this.ToInventDimId : this.InventDimId;
}

public static MobRegistrations SaveRequest(List                     _lines,
                                           MobInventRefType         _inventRefType,
                                           InventRefId              _inventRefId = '',
                                           boolean                  _flipSign = false)
{
    ListEnumerator                  lEnum = _lines.getEnumerator();
    ListEnumerator                  registrations;
    TFMRequestLineElement           line;
    TFMRequestRegistrationElement   registration;
    //int                     n;
    MobRegistrations                MobRegistrations;
    MobRegistrations                MobRegistrationsTake;
    MobRegistrations                MobRegistrationsPlace;
    MobRegistrations                MobRegistrationsNew;
    MobRegistrations                firstMobRegistrations;
    InventDim                       inventDimIssue;
    InventDim                       inventDimReceipt;
    UnitOfMeasureSymbol             UnitTo;
    InventDim                       inventDim;
    boolean                         firstMobRegistrationsNew = true;
    InventQty                       qtyPlace;
    InventQty                       qtyPlaceSum;
    boolean                         takeFound = false;
    ItemId                          itemId;
    EcoResProduct                   ecoResProduct;
    TFMDocumentMessageId            messageId;
    MobRegistrationsExtraInfo       mobRegistrationsExtraInfo;
    Map                             extraInfoFieldMap;
    MapEnumerator                   extraInfoEnum;
    str                             labelString = TFMConstants::AttributeLabel();

    while (lEnum.moveNext())
    {
        line = lEnum.current();
        MobRegistrations.clear();
        messageId = line.parmRoot().parmmessageId();
        MobRegistrations.MessageId = messageId;
        registrations = line.Registrations().getEnumerator();
        while (registrations.moveNext())
        {
            inventDimIssue.clear();
            inventDimReceipt.clear();
            registration = registrations.current();

            MobRegistrations.InventRefType			= _inventRefType;
            MobRegistrations.InventRefId			= _inventRefId;
            MobRegistrations.ToteID					= registration.parmToteId();
            MobRegistrations.expDate				= registration.parmExpirationDate();
            MobRegistrations.Qty					= registration.parmQuantity() * (_flipSign ? -1 : 1);
            MobRegistrations.Unit					= registration.parmUnitOfMeasure();
            MobRegistrations.Handled				= NoYes::No;

            if (InventTrans::findTransId(line.parmLineNumber()))
            {
                MobRegistrations.InventTransId         = line.parmLineNumber();
            }
            else if (InventTransOrigin::findByInventTransId(line.parmLineNumber()))
            {
                MobRegistrations.InventTransId         = line.parmLineNumber();
            }
            else if (InventJournalTrans::findInventTransId(line.parmLineNumber()) && _inventRefType == MobInventRefType::InventJournal)
            {
                MobRegistrations.InventTransId         = line.parmLineNumber();
            }
            else
            {
                MobRegistrations.RefRecId              = str2int64(line.parmLineNumber());
            }

            MobRegistrations.ReturnDispositionCodeId = '';

            if (registration.ExtraInfo() != null )
            {
                MobRegistrations.ReturnDispositionCodeId = registration.ExtraInfo().parmRMA_CauseId();
            }

            if (registration.ExtraInfo() != null && !MobRegistrations.InventTransId)
            {
                MobRegistrations.InventTransId = registration.ExtraInfo().parmInventTransId();
            }

            if (registration.ExtraInfo() != null )
            {
                itemId =  registration.ExtraInfo().parmItemId();
            }

            if (!itemId)
            {
                itemId = MobRegistrations.ItemNumber();
            }

            if (!itemId)
            {
                MobRegistrationsErrors::LogError(MobRegistrations.MessageId,MobRegistrations, strFmt("@TFM:Linenotfoundin",_inventRefType));
                //continue;
            }

            /*if (TFMInventRefType::InventArrival == _inventRefType)
            {

                MobRegistrations.InventTransId = WMSJournalTrans::find(MobRegistrations.InventRefId, str2num(strReplace(MobRegistrations.InventTransId, ',', '.'))).InventTransId;
            }*/
            MobRegistrations.InventQty = MobRegistrations.Qty;
            ecoResProduct = InventTable::find(itemId).Product();
            if (MobRegistrations.Unit)
            {
                UnitTo = InventTable::find(itemId).inventUnitId();
                MobRegistrations.InventQty             = UnitOfMeasureConverter::convert(  MobRegistrations.Qty,
                                                            UnitOfMeasure::findBySymbol( MobRegistrations.Unit).RecId,
                                                            UnitOfMeasure::findBySymbol( UnitTo ).RecId,
                                                            true,
                                                            ecoResProduct.RecId);
                MobRegistrations.Unit = UnitTo;
            }

            MobRegistrations.ActionType = registration.parmActionType();
            switch(MobRegistrations.ActionType)
            {
                case TFMActionTypes::TAKE :

                    inventDimIssue = registration.ExtractInventDim(itemId);
                    TFMHelper::EnsureInventDim(inventDimIssue);
                    MobRegistrations.InventDimId       = InventDim::findOrCreate(inventDimIssue).inventDimId;
                    break;

                case TFMActionTypes::PLACE :

                    inventDimReceipt = registration.ExtractInventDim(itemId);
                    TFMHelper::EnsureInventDim(inventDimReceipt,MobRegistrations.InventTransId);
                    MobRegistrations.ToInventDimId     = InventDim::findOrCreate(inventDimReceipt).inventDimId;
                    break;

                /*default :
                    TFMHelper::ExtractInventDim(inventDimIssue, ItemId, registrationNode, #FromLocation, 'LotNumber', 'SerialNumber');
                    TFMHelper::EnsureInventDim(inventDimIssue);
                    MobRegistrations.InventDimId       = InventDim::findOrCreate(inventDimIssue).inventDimId;
                    TFMHelper::ExtractInventDim(inventDimReceipt, ItemId, registrationNode, #ToLocation, 'LotNumber', 'SerialNumber');
                    TFMHelper::EnsureInventDim(inventDimReceipt);
                    MobRegistrations.ToInventDimId     = InventDim::findOrCreate(inventDimReceipt).inventDimId;
                    break;*/
            }

            /*MobRegistrations.initFromLineNode(lineNode);
            MobRegistrations.initFromRegistrationNode(registrationNode);*/

            MobRegistrations.insert();

            if (! firstMobRegistrations)
            {
                firstMobRegistrations = MobRegistrations;
            }

            // Save extra info
            if(registration.ExtraInfo() != null)
            {
                extraInfoFieldMap = registration.ExtraInfo().getFieldMap();  
                extraInfoEnum = extraInfoFieldMap.getEnumerator();
                mobRegistrationsExtraInfo.MobRegistration = MobRegistrations.RecId;
                while(extraInfoEnum.moveNext())
                {
                    mobRegistrationsExtraInfo.Key = extraInfoEnum.currentKey();
                    if(subStr(mobRegistrationsExtraInfo.Key, strLen(mobRegistrationsExtraInfo.Key), -5) != labelString)  // skip labeldata
                    {
                        mobRegistrationsExtraInfo.Value = extraInfoEnum.currentValue();
                        mobRegistrationsExtraInfo.insert();
                    }
                }
            }

        }
    }

    while select forupdate MobRegistrationsPlace
        index OrderLineNumIdx
        where MobRegistrationsPlace.InventRefType == _inventRefType &&
              MobRegistrationsPlace.InventRefId   == _inventRefId &&
              MobRegistrationsPlace.handled       == NoYes::No &&
              MobRegistrationsPlace.ActionType    == TFMActionTypes::PLACE
    {
        takeFound = false;
        qtyPlaceSum = 0;
        qtyPlace = MobRegistrationsPlace.InventQty;

        while select forupdate MobRegistrationsTake
            index OrderLineNumIdx
            where MobRegistrationsTake.InventRefType   == _inventRefType &&
                  MobRegistrationsTake.InventRefId     == _inventRefId &&
                  MobRegistrationsTake.handled         == NoYes::No &&
                  MobRegistrationsTake.ActionType      == TFMActionTypes::TAKE &&
                  ((_inventRefType == MobInventRefType::None &&
                    MobRegistrationsTake.RefRecId              == MobRegistrationsPlace.RefRecId) ||
                   (_inventRefType != MobInventRefType::None &&
                    MobRegistrationsTake.InventTransId         == MobRegistrationsPlace.InventTransId))
            join inventDim
                where inventDim.inventDimId     == MobRegistrationsTake.InventDimId &&
                      inventDim.inventBatchId   == InventDim::find(MobRegistrationsPlace.ToInventDimId).inventBatchId &&
                      inventDim.inventSerialId  == InventDim::find(MobRegistrationsPlace.ToInventDimId).inventSerialId
        {
            takeFound = true;

            if (qtyPlace)
            {
                if(MobRegistrationsTake.InventQty < qtyPlace)
                {
                    qtyPlace = MobRegistrationsTake.InventQty;
                }

                MobRegistrationsNew.clear();
                MobRegistrationsNew.MessageId       = messageId;
                MobRegistrationsNew.InventRefType   = _inventRefType;
                MobRegistrationsNew.InventRefId     = _inventRefId;
                MobRegistrationsNew.expDate         = MobRegistrationsTake.expDate;
                MobRegistrationsNew.InventQty       = qtyPlace;
                MobRegistrationsNew.Unit            = MobRegistrationsTake.Unit;
                MobRegistrationsNew.Handled         = NoYes::No;
                MobRegistrationsNew.RefRecId        = MobRegistrationsTake.RefRecId;
                MobRegistrationsNew.InventTransId   = MobRegistrationsTake.InventTransId;
                MobRegistrationsNew.InventDimId     = MobRegistrationsTake.InventDimId;
                MobRegistrationsNew.ToInventDimId   = MobRegistrationsPlace.ToInventDimId;
                MobRegistrationsNew.insert();

                if (firstMobRegistrationsNew)
                {
                    firstMobRegistrationsNew        = false;
                    firstMobRegistrations           = null;
                    firstMobRegistrations           = MobRegistrationsNew;
                }

                MobRegistrationsTake.InventQty -= qtyPlace;
                qtyPlaceSum += qtyPlace;
                qtyPlace = MobRegistrationsPlace.InventQty - qtyPlaceSum;
                if (MobRegistrationsTake.InventQty == 0)
                {
                    MobRegistrationsTake.handled = NoYes::Yes;
                }
                MobRegistrationsTake.Update();
            }
        }

        // Only update the PLACE registration if a take line was found
        // In situations where the mobile device only delivers PLACE registrations
        // it is important that they are NOT marked as handled
        if (takeFound)
        {
            MobRegistrationsPlace.handled = NoYes::Yes;
            MobRegistrationsPlace.Update();
        }
    }

    return firstMobRegistrations;
}

// Copied from Class WmsJournalTransSplit.serverRun()
private server static WMSJournalTrans WmsJournalTransSplit(WMSJournalTrans _wmsJournalTransOrig, InventQty _splitQty )
{
    #OCCRetryCount
    SalesLine               salesLine;
    WMSJournalTrans         transOrig;
    WMSJournalTrans         transSplit;

    setprefix(WMSJournalTransSplit::description());

    try
    {
        ttsbegin;
        if (_wmsJournalTransOrig.ReturnItemNum && _wmsJournalTransOrig.InventTransType == InventTransType::Sales)
        {
            if (ReturnDispositionCode::find(_wmsJournalTransOrig.ReturnDispositionCodeId).createReplacement())
            {
                salesLine = SalesLine::findInventTransId(_wmsJournalTransOrig.InventTransId);
                if (ReturnReplaceItemRef::deleteReplaceSetup(salesLine.SalesId, salesLine.LineNum))
                {
                    //One or more Replacement orders, related to Arrival journal %1 line number %2 and return order %3, has been deleted.
                    info(strfmt("@SYS116538", _wmsJournalTransOrig.JournalId, _wmsJournalTransOrig.LineNum, _wmsJournalTransOrig.ReturnItemNum));
                }
            }
        }

        transOrig = WMSJournalTrans::find(_wmsJournalTransOrig.JournalId, _wmsJournalTransOrig.LineNum, true);
        transOrig.Qty = transOrig.Qty - _splitQty;
        transOrig.update();

        transSplit.data(_wmsJournalTransOrig);

        if(_wmsJournalTransOrig.ReturnItemNum && _wmsJournalTransOrig.InventTransType == InventTransType::Sales)
        {
            transSplit.InventTransId = SalesLine::splitReturnLine(transOrig.InventTransId, _splitQty*-1);
            SalesLine::changeReturnOrderType(transSplit.InventTransId);
        }

        transSplit.Qty                      = _splitQty;
        transSplit.ReturnDispositionCodeId  = '';
        transSplit.LineNum                  = 0;
        transSplit.insert();
        ttscommit;

        return transSplit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

